    photo:"Tu foto aquí", tagline:"Está de cumpleaños", scroll:"Desliza",
    invited:"Estás invitado",
    f_name:"Invitado", f_people:"Lugares", f_desc:"Acceso", f_status:"Estado", f_msg:"Nota",
    q1:"Treinta vueltas al sol.<br>Mil historias.<br>Una sola noche para celebrarlas.",
    q2:"Ven con hambre, con ganas de bailar<br>y sin planes para mañana.",
    c_d:"Días", c_h:"Horas", c_m:"Min", c_s:"Seg",
    where:"Cuándo y dónde", when:"Fecha", address:"Lugar", map:"Ver mapa", addcal:"Agendar", ics:"Descargar .ics",
    lodging:"Dónde quedarte", lodging_t:"Opciones cerca del lugar, por si la noche se alarga.", hotels:"Ver opciones",
