/* =====================================================================
   DATA  +  helpers
   ===================================================================== */
const CFG = JSON.parse(document.getElementById("invitation-data").textContent);
const $  = (s,r=document)=>r.querySelector(s);
const $$ = (s,r=document)=>[...r.querySelectorAll(s)];
const store = { get(k){try{return localStorage.getItem(k)}catch{return null}}, set(k,v){try{localStorage.setItem(k,v)}catch{}} };

const AVAILABLE = CFG.languages?.available?.length ? CFG.languages.available : ["es","en"];
let lang = store.get("inv-lang") || CFG.languages?.default || (navigator.language||"es").slice(0,2);
if(!AVAILABLE.includes(lang) || !T[lang]) lang = CFG.languages?.default || "es";

